 def own(self,route,**data):
  data.setdefault('request_key',secrets.token_hex(32));return self.owner.post(self.base+'/prospect-api.php?mode=owner&r='+route,json=data)
 def exchange(self,token):
  g=requests.Session();r=g.post(self.base+'/prospect-api.php?r=exchange',headers={'X-Neuro-Exchange':'1'},json={'token':token});return g,r
 def consent(self,g,r):
  g.headers['X-CSRF-Token']=r.json()['csrf'];r=g.post(self.base+'/prospect-api.php?r=consent',json={'consent':True,'policy_version':self.policy['version']});self.assertEqual(r.status_code,200,r.text)
