  r=self.owner.post(self.base+'/api.php?r=crm/projects',json={'customer_id':self.customer_id,'title':'SYNTHETIC prospect project','description':'SYNTHETIC confirmed prospect brief: build an isolated landing page with an accessible inquiry form and documented acceptance criteria, no real deployment.','request_key':secrets.token_hex(32)});self.project_id=int(self.must(r)['record']['id']);t,q=self.prepare();proposal=self.must(self.generate(t,q))['record'];agreement=self.must(self.generate(self.approved_template('agreement'),q))['record'];tz=self.must(self.generate(self.approved_template('specification'),q))['record'];oid=int(agreement['order_id']);self.must(self.lp('flow/orders',project_id=self.project_id));self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_customer_accounts WHERE customer_id=?',params=[self.customer_id])[0]['n'],0)
  return oid,[proposal,agreement,tz]
